{
  "title": "Weekend Trip Checklist",
  "body": "<div class="todo-container">
  <header class="todo-header">
    <div class="title-wrap">
      <span class="badge-icon">🏕️</span>
      <div>
        <h2 class="title">Weekend Trip</h2>
        <p class="subtitle">Shared planner & to-do list</p>
      </div>
    </div>
    <div class="status-pill">
      <span id="todo-count" class="count-text">0 items left</span>
    </div>
  </header>

  <div class="progress-track">
    <div id="progress-fill" class="progress-fill"></div>
  </div>

  <form id="todo-form" class="input-row">
    <input id="todo-input" type="text" placeholder="Add something to pack or prepare..." />
    <button id="add-btn" type="submit" class="add-btn">Add</button>
  </form>

  <ul id="todo-list" class="todo-list"></ul>
</div>",
  "css": "* {
  box-sizing: border-box;
}

.todo-container {
  padding: 18px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #1e293b;
  background: #ffffff;
  border-radius: 12px;
  max-width: 480px;
  margin: 0 auto;
}

.todo-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.title-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
}

.badge-icon {
  font-size: 26px;
  line-height: 1;
}

.title {
  font-size: 18px;
  font-weight: 700;
  margin: 0;
  color: #0f172a;
}

.subtitle {
  font-size: 12px;
  color: #64748b;
  margin: 2px 0 0 0;
}

.status-pill {
  background: #f1f5f9;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid #e2e8f0;
}

.count-text {
  font-size: 12px;
  font-weight: 600;
  color: #475569;
}

.progress-track {
  height: 6px;
  background: #f1f5f9;
  border-radius: 999px;
  overflow: hidden;
  margin-bottom: 16px;
}

.progress-fill {
  height: 100%;
  background: #10b981;
  width: 0%;
  transition: width 0.25s ease;
}

.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

.input-row input {
  flex: 1;
  padding: 10px 14px;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  font-size: 14px;
  outline: none;
  background: #f8fafc;
  color: #0f172a;
}

.input-row input:focus {
  border-color: #3b82f6;
  background: #ffffff;
}

.add-btn {
  padding: 10px 16px;
  background: #0284c7;
  color: #ffffff;
  border: none;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}

.add-btn:hover {
  background: #0369a1;
}

.todo-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.todo-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  transition: background 0.15s ease;
}

.todo-item:hover {
  background: #f1f5f9;
}

.todo-item.completed {
  background: #fcfcfd;
  border-color: #f1f5f9;
}

.todo-label {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  flex: 1;
  min-width: 0;
}

.todo-checkbox {
  width: 17px;
  height: 17px;
  cursor: pointer;
  accent-color: #10b981;
}

.todo-text {
  font-size: 14px;
  color: #334155;
  word-break: break-word;
}

.todo-item.completed .todo-text {
  text-decoration: line-through;
  color: #94a3b8;
}

.delete-btn {
  background: transparent;
  border: none;
  color: #94a3b8;
  font-size: 18px;
  line-height: 1;
  padding: 4px 6px;
  cursor: pointer;
  border-radius: 4px;
  margin-left: 8px;
}

.delete-btn:hover {
  color: #ef4444;
  background: #fee2e2;
}",
  "scripts": [
    "const initialTodos = [
  { id: 1, text: "Book cabin & check weather forecast", done: false },
  { id: 2, text: "Pack hiking boots & warm layers", done: false },
  { id: 3, text: "Curate road trip playlist & pack snacks", done: true }
];

if (!state.todos) {
  state.todos = initialTodos;
  state.nextId = 4;
}

const form = root.querySelector('#todo-form');
const input = root.querySelector('#todo-input');
const list = root.querySelector('#todo-list');
const countEl = root.querySelector('#todo-count');
const progressFill = root.querySelector('#progress-fill');

const render = () => {
  const remaining = state.todos.filter((t) => !t.done).length;
  const total = state.todos.length;
  const pct = total === 0 ? 0 : Math.round(((total - remaining) / total) * 100);

  if (countEl) {
    countEl.textContent = `${remaining} ${remaining === 1 ? 'item' : 'items'} left`;
  }

  if (progressFill) {
    progressFill.setAttribute('style', `width: ${pct}%`);
  }

  list.replaceChildren();

  for (const todo of state.todos) {
    const li = root.create('li');
    li.classList.add('todo-item');
    if (todo.done) {
      li.classList.add('completed');
    }

    const label = root.create('label');
    label.classList.add('todo-label');

    const chk = root.create('input');
    chk.setAttribute('type', 'checkbox');
    chk.classList.add('todo-checkbox');
    chk.checked = todo.done;
    chk.addEventListener('change', () => {
      todo.done = chk.checked;
      render();
    });

    const span = root.create('span');
    span.classList.add('todo-text');
    span.textContent = todo.text;

    label.append(chk);
    label.append(span);

    const delBtn = root.create('button');
    delBtn.classList.add('delete-btn');
    delBtn.textContent = '×';
    delBtn.addEventListener('click', () => {
      state.todos = state.todos.filter((item) => item.id !== todo.id);
      render();
    });

    li.append(label);
    li.append(delBtn);
    list.append(li);
  }
};

const addItem = () => {
  const text = input.value ? input.value.trim() : '';
  if (text.length > 0) {
    state.todos.push({
      id: state.nextId,
      text: text,
      done: false
    });
    state.nextId = state.nextId + 1;
    input.value = '';
    render();
  }
};

if (form) {
  form.addEventListener('submit', () => {
    addItem();
  });
}

const addBtn = root.querySelector('#add-btn');
if (addBtn) {
  addBtn.addEventListener('click', () => {
    addItem();
  });
}

render();"
  ]
}
